  // A trailing '\r' on the final line of a file with no EOF newline is content, not a line
  // ending, so it must not be mistaken for a Windows line ending and stripped.
  const oldFile = 'line1\nline2\n';
  const newFile = 'line1\nline2\nline3\r';
  const patch = structuredPatch('f', 'f', oldFile, newFile, undefined, undefined, {context: 0});
